const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const n = input[idx++], m = input[idx++];

const a = [];
for (let i = 0; i < n; i++) a.push(input[idx++]);

const b = [];
for (let i = 0; i < m; i++) b.push(input[idx++]);

// Check for common digit
let common = null;
const setB = new Set(b);
for (let d of a) {
    if (setB.has(d)) {
        if (common === null || d < common) common = d;
    }
}

if (common !== null) {
    console.log(common);
} else {
    // No common digit: smallest two-digit number formed by one from each list
    let minA = Math.min(...a);
    let minB = Math.min(...b);
    let num1 = minA * 10 + minB;
    let num2 = minB * 10 + minA;
    console.log(Math.min(num1, num2));
}

